#"'!/usr/bin/env python3
"""Send text prompts to OpenAI'"'s Responses API using only the standard library.\"\"\"

from __future__ import annotations

import argparse
import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any


API_URL = \"https://api.openai.com/v1/responses\"


class OpenAIError(RuntimeError):
    \"\"\"Raised when the Responses API request cannot be completed.\"\"\"


def send_prompt(
    prompt: str,
    *,
    model: str = \"gpt-5.1\",
    api_key: str | None = None,
    timeout: float = 60.0,
    **parameters: Any,
) -> dict[str, Any]:
    \"\"\"Send a private text prompt and return the parsed Responses API result.

    The API key defaults to the OPENAI_API_KEY environment variable and is sent
    only to the official OpenAI endpoint. Additional keyword arguments become
    top-level JSON request parameters, for example temperature=0.5.
    \"\"\"
    resolved_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
    if not resolved_key:
        raise OpenAIError(\"OPENAI_API_KEY is not set\")

    payload: dict[str, Any] = {
        \"model\": model,
        \"input\": prompt,
        **parameters,
    }
    request = urllib.request.Request(
        API_URL,
        data=json.dumps(payload, separators=(\",\", \":\")).encode(\"utf-8\"),
        headers={
            \"Authorization\": f\"Bearer {resolved_key}\",
            \"Content-Type\": \"application/json\",
        },
        method=\"POST\",
    )

    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            body = response.read().decode(\"utf-8\")
    except urllib.error.HTTPError as error:
        details = error.read().decode(\"utf-8\", errors=\"replace\")
        try:
            decoded = json.loads(details)
            message = decoded.get(\"error\", {}).get(\"message\", details)
        except json.JSONDecodeError:
            message = details
        raise OpenAIError(f\"HTTP {error.code}: {message}\") from error
    except (urllib.error.URLError, TimeoutError) as error:
        raise OpenAIError(f\"Request failed: {error}\") from error

    try:
        result = json.loads(body)
    except json.JSONDecodeError as error:
        raise OpenAIError(\"OpenAI returned invalid JSON\") from error
    if not isinstance(result, dict):
        raise OpenAIError(\"OpenAI returned an unexpected JSON value\")
    return result


def response_text(result: dict[str, Any]) -> str:
    \"\"\"Extract output text from a successful Responses API result.\"\"\"
    output = result.get(\"output\")
    if not isinstance(output, list):
        raise OpenAIError(\"Responses API result has no output list\")
    chunks: list[str] = []
    for item in output:
        if not isinstance(item, dict):
            continue
        for content in item.get(\"content\", []):
            if isinstance(content, dict) and content.get(\"type\") == \"output_text\":
                text = content.get(\"text\")
                if isinstance(text, str):
                    chunks.append(text)
    return \"\".join(chunks)


def main() -> int:
    parser = argparse.ArgumentParser(description=\"Send a text prompt to OpenAI.\")
    parser.add_argument(\"prompt\", help=\"private text prompt to send\")
    parser.add_argument(\"--model\", default=\"gpt-5.1\", help=\"model name\")
    parser.add_argument(\"--timeout\", type=float, default=60.0, help=\"seconds\")
    parser.add_argument(
        \"--json\",
        action=\"store_true\",
        help=\"print the complete JSON response instead of its text\",
    )
    arguments = parser.parse_args()

    try:
        result = send_prompt(
            arguments.prompt,
            model=arguments.model,
            timeout=arguments.timeout,
        )
        if arguments.json:
            print(json.dumps(result, indent=2, ensure_ascii=False))
        else:
            print(response_text(result))
    except OpenAIError as error:
        print(f\"error: {error}\", file=sys.stderr)
        return 1
    return 0


if __name__ == \"__main__\":
    raise SystemExit(main())
